<script setup>
import { ref, computed, nextTick } from 'vue'
import { useRouter } from 'vue-router'
import { useTasksStore } from '../../stores/tasksStore'
import { useUsersStore } from '../../stores/usersStore'
import { useListsStore } from '../../stores/listsStore'
import { usePreferencesStore } from '../../stores/preferencesStore'
import { relativeDay, isOverdue, relativeTimeAgo, formatDate, formatDateTime } from '../../utils/formatters'
import { useTaskPermissions } from '../../composables/usePermissions'
import { useAssignableUsers } from '../../composables/useAssignableUsers'
import { useClickOutside } from '../../composables/useClickOutside'
import { getInitials, getAvatarColor } from '../../utils/avatar'
import PriorityBadge from './PriorityBadge.vue'
import TaskContextMenu from './TaskContextMenu.vue'
import AppIcon from '../common/AppIcon.vue'

const props = defineProps({ task: { type: Object, required: true }, depth: { type: Number, default: 0 }, bubbleMode: { type: Boolean, default: false } })
const emit = defineEmits(['open'])
const router = useRouter(); const tasksStore = useTasksStore(); const usersStore = useUsersStore(); const listsStore = useListsStore(); const prefs = usePreferencesStore()
const expanded = ref(true); const editingTitle = ref(false); const titleDraft = ref(props.task.title); const titleInputEl = ref(null); const addingSubtask = ref(false); const subtaskDraft = ref(''); const subtaskInputEl = ref(null); const contextMenu = ref(null); const checklistExpanded = ref(false); const newInlineChecklistTitle = ref(''); const inlineChecklistInputEl = ref(null)
const children = computed(() => tasksStore.childrenOf(props.task.id)); const assignee = computed(() => usersStore.byId(props.task.assigneeId)); const list = computed(() => listsStore.byId(props.task.listId)); const overdue = computed(() => isOverdue(props.task.dueDate, props.task.status)); const isDone = computed(() => props.task.status === 'done')
const occurrenceBadgeLabel = computed(() => {
  if (!props.task.meetingTitle && !props.task.occurrenceDate) return null
  return [props.task.meetingTitle, props.task.occurrenceDate ? formatDateTime(props.task.occurrenceDate) : null].filter(Boolean).join(' · ')
})
function openOccurrenceMeeting() { if (props.task.meetingId) router.push(`/meetings/${props.task.meetingId}`) }
const checklistItems = computed(() => tasksStore.checklistByTask[props.task.id]); const checklistCount = checklistItems; const commentsCount = computed(() => tasksStore.commentsByTask[props.task.id]?.length)
const { canEditThisTask, canToggleStatus, reason: permissionReason } = useTaskPermissions(() => props.task)
const assignPickerOpen = ref(false); const avatarBtnEl = ref(null); const dropdownEl = ref(null); const dropdownPos = ref({ top: 0, left: 0 }); const assignableUsers = useAssignableUsers(() => props.task); useClickOutside(dropdownEl, () => { assignPickerOpen.value = false })
function toggleAssignPicker() { if (!canEditThisTask.value) return; if (assignPickerOpen.value) { assignPickerOpen.value = false; return }; const rect = avatarBtnEl.value.getBoundingClientRect(); const dropdownW = 220; const estimatedH = Math.min(260, 40 + assignableUsers.value.length * 34); let left = Math.min(Math.max(8, rect.right - dropdownW), window.innerWidth - dropdownW - 8); let top = rect.bottom + 4; if (top + estimatedH > window.innerHeight - 8) top = Math.max(8, rect.top - estimatedH - 4); dropdownPos.value = { top, left }; assignPickerOpen.value = true }
function quickAssign(userId) { tasksStore.assignTask(props.task.id, userId); assignPickerOpen.value = false }
const datePickerOpen = ref(false); const dueDateBtnEl = ref(null); const datePickerEl = ref(null); const datePickerPos = ref({ top: 0, left: 0 }); const customDate = ref(''); useClickOutside(datePickerEl, () => { datePickerOpen.value = false })
function toLocalYYYYMMDD(date) { const d = new Date(date); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}` }; function offsetDate(days) { const d = new Date(); d.setDate(d.getDate()+days); return d }
function openDatePicker(e) { if (!canEditThisTask.value) return; e.stopPropagation(); datePickerOpen.value = !datePickerOpen.value; customDate.value = props.task.dueDate ? toLocalYYYYMMDD(props.task.dueDate) : toLocalYYYYMMDD(new Date()) }
function applyDate(value) { tasksStore.rescheduleTask(props.task.id, (value instanceof Date ? value : new Date(value)).toISOString()); datePickerOpen.value = false }; function clearDueDate() { tasksStore.rescheduleTask(props.task.id, null); datePickerOpen.value = false }; function applyCustomDate() { if (customDate.value) applyDate(customDate.value) }
const DATE_PRESETS = [{ label:'Сегодня', days:0 }, { label:'Завтра', days:1 }, { label:'Через 3 дня', days:3 }, { label:'Через неделю', days:7 }]; const PRIORITY_COLOR = { low:'#9aa3b2', medium:'#4f7cff', high:'#e8a13a', urgent:'#e5484d' }; const PRIORITY_LABEL = { low:'Низкий', medium:'Средний', high:'Высокий', urgent:'Срочный' }; const PRIORITIES = ['low','medium','high','urgent']; const priorityPickerOpen = ref(false); const priorityBadgeBtnEl = ref(null); const priorityPickerEl = ref(null); const priorityPickerPos = ref({ top:0,left:0 }); useClickOutside(priorityPickerEl, () => { priorityPickerOpen.value = false })
function openPriorityPicker(e) { if (!canEditThisTask.value) return; e.stopPropagation(); priorityPickerOpen.value = !priorityPickerOpen.value }; function applyPriority(priority) { tasksStore.updateTaskField(props.task.id,'priority',priority); priorityPickerOpen.value = false }
const rowAccentColor = computed(() => prefs.colorCode === 'priority' ? PRIORITY_COLOR[props.task.priority] : prefs.colorCode === 'list' ? list.value?.color : prefs.colorCode === 'overdue' ? (overdue.value ? '#e5484d' : 'transparent') : prefs.colorCode === 'assignee' ? (assignee.value ? '#4f7cff' : 'transparent') : 'transparent')
function toggleComplete() { if (!canToggleStatus.value) return; isDone.value ? tasksStore.reopenTask(props.task.id) : tasksStore.completeTask(props.task.id) }; function snooze() { const d = new Date(props.task.dueDate || new Date()); d.setDate(d.getDate()+1); tasksStore.rescheduleTask(props.task.id,d.toISOString()) }; function startEditTitle() { titleDraft.value=props.task.title; editingTitle.value=true; nextTick(()=>titleInputEl.value?.focus()) }; function commitTitle() { editingTitle.value=false; const v=titleDraft.value.trim(); if(v&&v!==props.task.title) tasksStore.updateTaskField(props.task.id,'title',v) }; function cancelEditTitle() { editingTitle.value=false; titleDraft.value=props.task.title }; function startAddSubtask() { addingSubtask.value=true; expanded.value=true; subtaskDraft.value=''; nextTick(()=>subtaskInputEl.value?.focus()) }; async function commitSubtask(keepOpen=false) { const title=subtaskDraft.value.trim(); if(title) await tasksStore.createTask({ listId:props.task.listId,parentTaskId:props.task.id,title,priority:props.task.priority,assigneeId:props.task.assigneeId }); subtaskDraft.value=''; if(keepOpen&&title) nextTick(()=>subtaskInputEl.value?.focus()); else addingSubtask.value=false }; function cancelAddSubtask() { addingSubtask.value=false; subtaskDraft.value='' }; async function toggleChecklistExpand() { checklistExpanded.value=!checklistExpanded.value; if(checklistExpanded.value&&!tasksStore.checklistByTask[props.task.id]) await tasksStore.loadChecklist(props.task.id); if(checklistExpanded.value) nextTick(()=>inlineChecklistInputEl.value?.focus()) }; function toggleChecklistDone(id) { tasksStore.toggleChecklistItem(props.task.id,id) }; async function addInlineChecklistItem() { const title=newInlineChecklistTitle.value.trim(); if(!title)return; await tasksStore.addChecklistItem(props.task.id,title); newInlineChecklistTitle.value='' }; function removeInlineChecklistItem(id) { tasksStore.removeChecklistItem(props.task.id,id) }; function openContextMenu(e) { e.preventDefault(); contextMenu.value={x:e.clientX,y:e.clientY} }; function closeContextMenu() { contextMenu.value=null }
</script>

<template>
  <div class="task-row-wrapper"><div class="task-row" :class="[`density-${prefs.density}`,{done:isDone,overdue:overdue&&prefs.highlightOverdue,'bubble-overdue':bubbleMode&&overdue}]" :style="{paddingLeft:`${8+depth*22}px`,borderLeftColor:rowAccentColor,borderLeftWidth:rowAccentColor!=='transparent'?'9px':'0'}" @contextmenu="openContextMenu"><button v-if="children.length" class="expand-btn" @click="expanded=!expanded"><AppIcon :name="expanded?'chevronDown':'chevronRight'" :size="12" /></button><span v-else class="expand-spacer" /><input type="checkbox" :checked="isDone" class="task-checkbox" :disabled="!canToggleStatus" :title="canToggleStatus?'':permissionReason" @change="toggleComplete" /><div class="task-main"><input v-if="editingTitle" ref="titleInputEl" v-model="titleDraft" class="title-edit-input" @blur="commitTitle" @keyup.enter="commitTitle" @keyup.escape="cancelEditTitle" /><span v-else class="task-title" :class="{'wrap-title':prefs.wrapLongTitles,'truncate-title':!prefs.wrapLongTitles}" @click="emit('open',task)" @dblclick.stop="startEditTitle"><span v-if="task.pinned" class="pin-icon"><AppIcon name="pin" :size="12" /></span>{{task.title}}<span v-if="prefs.showSubtaskCount&&children.length" class="mini-count"><AppIcon name="link" :size="11" />{{children.length}}</span><span v-if="prefs.showChecklistProgress&&(checklistCount?.length||checklistExpanded)" class="mini-count mini-count-clickable" @click.stop="toggleChecklistExpand"><AppIcon name="checklist" :size="11" />{{checklistCount?.filter(i=>i.done).length||0}}/{{checklistCount?.length||0}}</span><span v-if="prefs.showCommentsCount&&commentsCount" class="mini-count"><AppIcon name="message" :size="11" />{{commentsCount}}</span></span><div v-if="!editingTitle" class="task-meta"><span v-if="prefs.showCreatedDate&&task.createdAt" class="date-meta"><AppIcon name="plus" :size="11" /> создано {{relativeTimeAgo(task.createdAt)}}</span><span v-if="prefs.showDueDate" ref="dueDateBtnEl" class="due-date" :class="{'due-overdue':overdue,'due-date-clickable':canEditThisTask}" @click.stop="openDatePicker"><AppIcon name="calendar" :size="11" />{{task.dueDate?relativeDay(task.dueDate):'срок не установлен'}}</span><span ref="priorityBadgeBtnEl" :class="['badge',`badge-${task.priority}`]" @click.stop="openPriorityPicker">{{PRIORITY_LABEL[task.priority]}}</span><button v-if="occurrenceBadgeLabel" class="tag occurrence-badge" :title="'Подвстреча: '+occurrenceBadgeLabel" @click.stop="openOccurrenceMeeting"><AppIcon name="repeat" :size="11" /> {{occurrenceBadgeLabel}}</button><span v-if="prefs.showCompletedDate&&task.completedAt" class="date-meta"><AppIcon name="check" :size="11" />{{formatDate(task.completedAt)}}</span><span v-if="prefs.showLastUpdatedDate&&task.updatedAt" class="date-meta"><AppIcon name="edit" :size="11" />{{relativeTimeAgo(task.updatedAt)}}</span><span v-if="prefs.showListBadgeInMyTasks&&list" class="tag list-badge" :style="{background:list.color+'22',color:list.color}">{{list.title}}</span><span v-if="prefs.showTags&&task.tags?.length" v-for="tag in task.tags" :key="tag" class="tag">{{tag}}</span><span v-if="prefs.showWatchers&&task.watcherIds?.length" class="tag watcher-tag"><AppIcon name="eye" :size="11" />{{task.watcherIds.length}}</span></div></div><div v-if="prefs.showAssigneeAvatar" class="task-assignee"><button ref="avatarBtnEl" class="avatar-btn" @click.stop="toggleAssignPicker"><span v-if="assignee" class="avatar" :style="{background:getAvatarColor(assignee.name)}">{{getInitials(assignee.name)}}</span><span v-else class="avatar avatar-empty">+</span></button></div><div class="task-quick-actions"><button v-if="canEditThisTask" class="btn btn-ghost btn-sm" @click.stop="startAddSubtask"><AppIcon name="plus" :size="13" /></button><button v-if="canEditThisTask" class="btn btn-ghost btn-sm" @click.stop="toggleChecklistExpand"><AppIcon name="checklist" :size="13" /></button><button v-if="canEditThisTask" class="btn btn-ghost btn-sm" @click.stop="snooze"><AppIcon name="alarm" :size="13" /></button></div></div>
    <div v-if="expanded&&(children.length||addingSubtask)" class="task-children"><TaskRow v-for="child in children" :key="child.id" :task="child" :depth="depth+1" :bubble-mode="bubbleMode" @open="emit('open',$event)" /><div v-if="addingSubtask" class="subtask-add-row"><span class="subtask-add-icon"><AppIcon name="link" :size="11" /></span><input ref="subtaskInputEl" v-model="subtaskDraft" class="subtask-add-input" placeholder="Название подзадачи" @keyup.enter="commitSubtask(true)" @keyup.escape="cancelAddSubtask" @blur="commitSubtask(false)" /></div></div>
    <TaskContextMenu v-if="contextMenu" :task="task" :x="contextMenu.x" :y="contextMenu.y" :checklist-expanded="checklistExpanded" @close="closeContextMenu" @open-detail="emit('open',$event)" @add-subtask="startAddSubtask" @rename="startEditTitle" @toggle-checklist="toggleChecklistExpand" />
  </div>
</template>

<style scoped>
.task-row{display:flex;align-items:center;gap:8px;padding:8px 10px;border-bottom:1px solid var(--color-border);background:var(--color-surface);border-left:0 solid transparent}.task-row.density-compact{padding-top:4px;padding-bottom:4px}.task-row.density-comfortable{padding-top:8px;padding-bottom:8px}.task-row.density-spacious{padding-top:14px;padding-bottom:14px}.task-row:hover{background:#fafbfe}.task-row.done .task-title{color:var(--color-text-muted);text-decoration:line-through}.task-row.overdue .due-date{color:var(--color-danger);font-weight:600}.task-row.bubble-overdue{background:rgba(229,72,77,.07)}.expand-btn{border:none;background:none;cursor:pointer;width:16px;color:var(--color-text-muted);display:flex;align-items:center;justify-content:center}.expand-spacer{width:16px;display:inline-block}.task-checkbox{accent-color:var(--color-primary);cursor:pointer}.task-checkbox:disabled{cursor:not-allowed;opacity:.45}.task-main{flex:1;min-width:0;display:flex;flex-direction:column;gap:3px}.task-title{font-size:13.5px;font-weight:500;display:flex;align-items:center;gap:6px;flex-wrap:wrap;cursor:pointer}.truncate-title{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.wrap-title{white-space:normal}.title-edit-input{font-size:13.5px;font-weight:500;border:1px solid var(--color-primary);border-radius:5px;padding:3px 6px;width:100%;outline:none}.pin-icon{display:flex;color:#c67d16}.mini-count{font-size:11px;color:var(--color-text-muted);display:inline-flex;align-items:center;gap:3px}.mini-count-clickable{cursor:pointer;padding:1px 5px;border-radius:4px}.task-meta{display:flex;align-items:center;gap:6px;flex-wrap:wrap}.due-date{font-size:11.5px;color:var(--color-text-muted);display:inline-flex;align-items:center;gap:3px}.due-date-clickable{cursor:pointer;border-radius:5px;padding:1px 5px}.due-overdue{color:var(--color-danger)!important;font-weight:600}.date-meta{font-size:11px;color:var(--color-text-muted);opacity:.75;white-space:nowrap;display:inline-flex;align-items:center;gap:3px}.list-badge{font-weight:600}.watcher-tag{background:#f4f0ff;color:#7c5cd6;display:inline-flex;align-items:center;gap:3px}.occurrence-badge{background:#eef2ff;color:var(--color-primary-dark);font-weight:600;border:none;cursor:pointer;display:inline-flex;align-items:center;gap:4px;font-size:11px;padding:2px 8px;border-radius:999px}.task-assignee{width:26px;flex-shrink:0;position:relative}.avatar-btn{border:none;background:none;padding:0;cursor:pointer;display:flex}.avatar{width:24px;height:24px;border-radius:50%;background:var(--color-primary);color:#fff;display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:700}.avatar-empty{background:#d9dde8;color:var(--color-text-muted)}.task-quick-actions{display:flex;gap:2px;opacity:1}.task-children{border-left:1px solid var(--color-border);margin-left:20px}.subtask-add-row{display:flex;align-items:center;gap:6px;padding:6px 10px;background:#fafbfe}.subtask-add-input{flex:1;border:1px dashed var(--color-border);border-radius:6px;padding:5px 8px;font-size:13px;outline:none}.inline-checklist{padding:6px 10px 8px;background:#fbfcfe;border-bottom:1px solid var(--color-border)}
</style>
